{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.Carlton_London_Myntra_FactItems as WITH orders AS ( SELECT order_id_fk, cast(order_release_id as string) order_release_id, store_order_id, order_line_id, seller_order_id, packet_id, order_tracking_number, sku_id, seller_sku_code, myntra_sku_code, vendor_article_number, style_id, style_name AS product_name, brand, size, article_type AS category, total_mrp AS mrp, seller_price, discount AS discount_price, coupon_discount, final_amount AS selling_price, tax_recovery, gift_charge, shipping_charge, gt_charges, CASE WHEN UPPER(ORDER_STATUS) = \'C\' THEN \'DELIVERED\' WHEN UPPER(ORDER_STATUS) = \'F\' THEN \'CANCELLED\' WHEN UPPER(ORDER_STATUS) = \'L\' THEN \'LOST\' WHEN UPPER(ORDER_STATUS) = \'PK\' THEN \'PACKED\' WHEN UPPER(ORDER_STATUS) = \'SH\' THEN \'SHIPPED\' WHEN UPPER(ORDER_STATUS) = \'RTO\' THEN \'RTO\' WHEN UPPER(ORDER_STATUS) = \'WP\' THEN \'OTHERS\' END AS order_status, cancellation_reason, city, state, cast(zipcode as string) zipcode, courier_code, seller_id AS seller_id_order, seller_warehouse_id, warehouse_id, CASE WHEN created_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR (created_on, 1, 19))) END AS created_date, CASE WHEN packed_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(packed_on, 1, 19))) END AS packed_date, CASE WHEN inscanned_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(inscanned_on, 1, 19))) END AS inscanned_date, CASE WHEN shipped_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(shipped_on, 1, 19))) END AS shipped_date, CASE WHEN delivered_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(delivered_on, 1, 19))) END AS delivered_date, CASE WHEN cancelled_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(cancelled_on, 1, 19))) END AS cancelled_date, CASE WHEN rto_creation_date = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(rto_creation_date, 1, 19))) END AS rto_creation_date, CASE WHEN return_creation_date = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(return_creation_date, 1, 19))) END AS return_creation_date, from maplemonk.Carlton_London_PPMP_myntra_custom_orders QUALIFY ROW_NUMBER() OVER (PARTITION BY seller_order_id, sku_id ORDER BY created_on DESC) = 1 ), returns AS ( SELECT return_id, exchange_id, cast(order_id as string) order_id, order_group_id, order_line_id, seller_order_id, store_packet_id, warehouse_id AS warehouse_id_return, sku_id, style_id, seller_id AS seller_id_return, seller_sku_code, myntra_sku_code, model, brand AS return_brand, type, quantity, return_reason, return_mode, return_status, status AS refund_status, is_refunded, forward_tracking_number, return_tracking_number, CASE WHEN lmdo_last_modified_on = \'\' THEN NULL ELSE PARSE_DATE(\'%Y-%m-%d\', SUBSTR(lmdo_last_modified_on,1,10)) END AS lmdo_last_modified_date, CASE WHEN order_created_date = \'\' THEN NULL ELSE PARSE_DATE(\'%Y-%m-%d\', SUBSTR(order_created_date,1,10)) END AS return_order_created_date, CASE WHEN inscanned_on = \'\' THEN NULL ELSE PARSE_DATE(\'%Y-%m-%d\', SUBSTR(inscanned_on,1,10)) END AS return_inscanned_date, CASE WHEN order_delivered_date = \'\' THEN NULL ELSE PARSE_DATE(\'%Y-%m-%d\', SUBSTR(order_delivered_date,1,10)) END AS return_order_delivered_date, CASE WHEN return_created_date = \'\' THEN NULL ELSE PARSE_DATE(\'%Y-%m-%d\', SUBSTR(return_created_date,1,10)) END AS return_created_date, CASE WHEN refunded_date = \'\' THEN NULL ELSE PARSE_DATE(\'%Y-%m-%d\', SUBSTR(refunded_date,1,10)) END AS refunded_date, CASE WHEN order_rto_date = \'\' THEN NULL ELSE PARSE_DATE(\'%Y-%m-%d\', SUBSTR(order_rto_date,1,10)) END AS order_rto_date from maplemonk.Carlton_London_PPMP_myntra_custom_returns QUALIFY ROW_NUMBER() OVER (PARTITION BY seller_order_id, sku_id ORDER BY order_created_date DESC) = 1 ) SELECT COALESCE(o.order_id_fk,r.order_group_id) Order_id_fk, COALESCE(o.order_release_id,r.order_id) Order_id, 1 AS Quantity, o.store_order_id, CAST(COALESCE(o.order_line_id, r.order_line_id) AS STRING) AS order_line_id, COALESCE(o.seller_order_id,r.seller_order_id) seller_order_id, COALESCE(o.packet_id,r.store_packet_id) Packet_id, o.order_tracking_number, COALESCE(o.sku_id,r.sku_id) Sku_Id, COALESCE(o.seller_sku_code,r.seller_sku_code) seller_sku_code, COALESCE(o.myntra_sku_code,r.myntra_sku_code) myntra_sku_code, o.vendor_article_number , COALESCE(o.style_id,r.style_id) style_id, o.product_name, o.brand , o.size, o.category sub_category, o.mrp , o.discount_price , o.coupon_discount , o.selling_price , o.tax_recovery Tax, o.shipping_charge, o.gt_charges , o.order_status , o.cancellation_reason , o.city , o.state , o.zipcode , o.courier_code , o.seller_id_order , o.seller_warehouse_id , o.warehouse_id , COALESCE(o.created_date ,r.return_order_created_date) Order_date, o.packed_date , COALESCE(o.inscanned_date,r.return_inscanned_date) Inscanned_date, o.shipped_date , cast(o.delivered_date as date) delivered_date, r.return_order_delivered_date, o.cancelled_date , o.return_creation_date , r.return_created_date, r.refunded_date, o.rto_creation_date , r.return_id, r.exchange_id, r.warehouse_id_return, r.seller_id_return, r.model, r.type Return_type, r.quantity return_quantity, r.return_reason, r.return_mode, r.return_status, r.refund_status, r.is_refunded, r.forward_tracking_number, r.return_tracking_number, null as product_id FROM orders o LEFT JOIN returns r ON o.seller_order_id = r.seller_order_id AND o.sku_id = r.sku_id;",
                    "transaction": true
                }
            ) }}
